import json, os, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd(); fz = repo / 'target/debug/fz'

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify_project(root):
    proc = subprocess.run([str(fz), 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return proc.returncode, payload

def build_with_backend(root, backend):
    env = dict(os.environ, FZ_GPU_BACKEND=backend)
    proc = subprocess.run([str(fz), 'build', str(root), '--json'], cwd=str(repo), env=env, capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    return proc.returncode, payload

def messages(payload):
    return [item['message'] for item in payload['items']]

abi_root = write_project('gpu_backend_reject_abi_shape', '''
    struct Pair { x: f32, y: f32 }
    use core.gpu;
    kernel fn blend(input: GpuSlice<f32>, coeff: Pair, output: GpuSlice<f32>) -> void {
        let i = gpu.global_id_x();
        output[i] = input[i] + coeff.x + coeff.y;
    }
    host fn main() -> i32 {
        return 0
    }
''')
abi_rc, abi_payload = verify_project(abi_root)
abi_messages = messages(abi_payload)
assert abi_rc == 1, (abi_rc, abi_payload)
assert any('kernel function `blend` parameter `coeff` uses type `Pair` that is not yet supported by the stable GPU launch ABI' in message for message in abi_messages), abi_messages
for backend in ['metal', 'spirv', 'nvptx']:
    rc, payload = build_with_backend(abi_root, backend)
    msgs = messages(payload)
    assert rc == 1, (backend, rc, payload)
    assert any('kernel function `blend` parameter `coeff` uses type `Pair` that is not yet supported by the stable GPU launch ABI' in message for message in msgs), (backend, msgs)
    assert not any('declared in the architecture but not yet executable' in message for message in msgs), (backend, msgs)
    assert not any('native backend cannot execute unresolved call `gpu.' in message for message in msgs), (backend, msgs)

match_root = write_project('gpu_backend_reject_match_shape', '''
    use core.gpu;
    device fn classify(flag: bool) -> i32 {
        match flag {
            true => return 1,
            _ => return 0,
        }
    }
    kernel fn write_value(output: GpuSlice<i32>) -> void {
        output[0] = classify(true);
    }
    host fn main() -> i32 {
        return 0
    }
''')
match_rc, match_payload = verify_project(match_root)
match_messages = messages(match_payload)
assert match_rc == 1, (match_rc, match_payload)
assert any('kernel lowering for `classify` failed: Kernel IR does not yet support `match` statements in GPU functions' in message for message in match_messages), match_messages
for backend in ['metal', 'spirv', 'nvptx']:
    rc, payload = build_with_backend(match_root, backend)
    msgs = messages(payload)
    assert rc == 1, (backend, rc, payload)
    assert any('kernel lowering for `classify` failed: Kernel IR does not yet support `match` statements in GPU functions' in message for message in msgs), (backend, msgs)
    assert not any('declared in the architecture but not yet executable' in message for message in msgs), (backend, msgs)
    assert not any('native backend cannot execute unresolved call `gpu.' in message for message in msgs), (backend, msgs)
print('compiler-gpu-backend-shape-rejections-ok')
